/* WARNING: Script requires that SQLITE_DBCONFIG_DEFENSIVE be disabled */
PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE comm_visits (id INTEGER PRIMARY KEY AUTOINCREMENT, ip_hash TEXT NOT NULL, visit_date TEXT NOT NULL, visit_hour INTEGER NOT NULL, is_revisit INTEGER DEFAULT 0, source TEXT DEFAULT 'DIRECT', page TEXT DEFAULT 'HOME', ua_class TEXT DEFAULT 'UNKNOWN', logged_at INTEGER NOT NULL, visitor_id TEXT, visitor_type TEXT DEFAULT 'PUBLIC');
CREATE TABLE comm_ops_events (id INTEGER PRIMARY KEY AUTOINCREMENT, event_type TEXT NOT NULL, priority TEXT DEFAULT 'MORNING', title TEXT NOT NULL, body TEXT NOT NULL, prospect_ref TEXT, triggered_at INTEGER NOT NULL, delivered INTEGER DEFAULT 0, dismissed INTEGER DEFAULT 0);
CREATE TABLE comm_actions (id INTEGER PRIMARY KEY AUTOINCREMENT, prospect_id INTEGER, action_type TEXT NOT NULL, status TEXT DEFAULT 'PENDING', due_at INTEGER, completed_at INTEGER, note TEXT, outcome TEXT, objection TEXT, logged_at INTEGER NOT NULL, force_feed INTEGER DEFAULT 0);
CREATE TABLE comm_prospects (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT NOT NULL,
  role TEXT,
  organisation TEXT,
  linkedin_url TEXT UNIQUE,
  score INTEGER DEFAULT 2,
  source_string TEXT DEFAULT 'S1',
  last_post_observed TEXT,
  personalisation_note TEXT,
  status TEXT DEFAULT 'SOURCED',
  interaction_count INTEGER DEFAULT 0,
  last_interaction_at INTEGER,
  added_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL,
  prospect_type TEXT DEFAULT 'LINKEDIN',
  whatsapp_number TEXT DEFAULT NULL,
  latest_wa_context TEXT DEFAULT NULL,
  wa_reply_override TEXT DEFAULT NULL
, snoozed_until TEXT DEFAULT NULL, latest_context TEXT DEFAULT NULL, reply_override TEXT DEFAULT NULL);
COMMIT;
